import type { Question } from './types'

const baseQuestions: Question[] = [
  {id:'24-tf-1',exam:'2024',section:'True or false',topic:'Stable matching',prompt:'The running time of the Gale–Shapley algorithm for stable matching is linear in the size of the input.',type:'true-false',options:['True','False'],answer:'True',explanation:'The solution manual states that Gale–Shapley is linear in the size of the input.'},
  {id:'24-tf-2',exam:'2024',section:'True or false',topic:'Stable matching',prompt:'If s ranks h first and h ranks s first, then s and h are matched in every stable matching.',type:'true-false',options:['True','False'],answer:'True',explanation:'Mutual first choices form a stable pair that must appear in every stable matching.'},
  {id:'24-tf-3',exam:'2024',section:'True or false',topic:'Minimum spanning trees',prompt:'If e is the unique minimum-weight edge, then e is in every minimum spanning tree.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution identifies this as true.'},
  {id:'24-tf-4',exam:'2024',section:'True or false',topic:'Minimum spanning trees',prompt:'If e has maximum weight in a cycle, then e cannot belong to any minimum spanning tree.',type:'true-false',options:['True','False'],answer:'False',explanation:'An edge with maximum weight on a cycle is not necessarily excluded from every MST.'},
  {id:'24-tf-5',exam:'2024',section:'True or false',topic:'Minimum spanning trees',prompt:'Adding 1 to every edge weight increases an MST cost by n.',type:'true-false',options:['True','False'],answer:'False',explanation:'An n-vertex MST has n − 1 edges, not n edges.'},
  {id:'24-tf-6',exam:'2024',section:'True or false',topic:'Minimum spanning trees',prompt:'With unique edge weights, the two smallest-weight edges are always in the MST.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks this statement true.'},
  {id:'24-tf-7',exam:'2024',section:'True or false',topic:'Shortest paths',prompt:'Adding a sufficiently large constant to every edge weight makes Dijkstra correct for negative-weight edges.',type:'true-false',options:['True','False'],answer:'False',explanation:'Shifting every edge weight does not preserve shortest paths when negative edges are allowed.'},
  {id:'24-tf-8',exam:'2024',section:'True or false',topic:'Complexity',prompt:'The 3-SAT problem is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A satisfying assignment can be verified in polynomial time.'},
  {id:'24-tf-9',exam:'2024',section:'True or false',topic:'Huffman encoding',prompt:'In a Huffman encoding of HENCHMEN, C and M are guaranteed to have equally long codewords.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks this statement true.'},
  {id:'24-tf-10',exam:'2024',section:'True or false',topic:'Flows',prompt:'In a flow network with positive capacities, every edge leaving s is saturated by every maximum flow.',type:'true-false',options:['True','False'],answer:'False',explanation:'Not every edge leaving s must carry its full capacity in a maximum flow.'},
  {id:'24-tf-11',exam:'2024',section:'True or false',topic:'Flows',prompt:'If 1 is added to every edge capacity, a previously minimum s-t cut remains minimum.',type:'true-false',options:['True','False'],answer:'False',explanation:'The cut with the fewest crossing edges may change because capacity increases differ.'},
  {id:'24-tf-12',exam:'2024',section:'True or false',topic:'Matchings',prompt:'A bipartite graph G = (V1,V2,E) has a perfect matching if and only if |V1| = |V2|.',type:'true-false',options:['True','False'],answer:'False',explanation:'Equal partition sizes are necessary but not sufficient for a perfect matching.'},
  {id:'24-tf-13',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n) = 2T(n/2) + n², then T(n) is Θ(n log n).',type:'true-false',options:['True','False'],answer:'False',explanation:'By the Master Theorem, this recurrence is Θ(n²), not Θ(n log n).'},
  {id:'24-tf-14',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n) = 2T(n/2) + n², then T(n) is Ω(n log n).',type:'true-false',options:['True','False'],answer:'True',explanation:'The recurrence is at least Ω(n²), so it is also Ω(n log n).'},
  {id:'24-tf-15',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n) = 5T(n/3) + n², then T(n) is O(n²).',type:'true-false',options:['True','False'],answer:'True',explanation:'The n² term dominates the recursion.'},
  {id:'24-mc-1',exam:'2024',section:'Fast algorithms',topic:'Graph algorithms',prompt:'What is the running time for checking whether an undirected graph has a cycle by comparing component edge and vertex counts?',type:'multiple-choice',options:['Θ(n)','Θ(n log n)','Θ(n²)','Θ(m log n)'],answer:'Θ(n)',explanation:'The official solution compares mC with nC − 1 in each component and gives Θ(n) time.'},
  {id:'24-mc-2',exam:'2024',section:'Fast algorithms',topic:'Graph algorithms',prompt:'What approach is recommended for checking whether a directed graph has a cycle?',type:'multiple-choice',options:['Run SCC and inspect component sizes','Run Dijkstra','Run Kruskal','Check every spanning tree'],answer:'Run SCC and inspect component sizes',explanation:'Run strongly connected components; a cycle exists if a component has more than one vertex.'},
  {id:'24-mc-3',exam:'2024',section:'More algorithms',topic:'Dynamic programming',prompt:'What running time does the official alarm-problem dynamic-programming solution give?',type:'multiple-choice',options:['Θ(n)','Θ(n log n)','Θ(n²)','Θ(2ⁿ)'],answer:'Θ(n)',explanation:'The recurrence fills a one-dimensional table in linear time.'},
  {id:'24-mc-4',exam:'2024',section:'More algorithms',topic:'Dynamic programming',prompt:'For a DAG whose vertices 1,...,n are already in topological order, what is the running time for finding a longest path?',type:'multiple-choice',options:['Θ(n + m)','Θ(n log n)','Θ(nm)','Θ(m log n)'],answer:'Θ(n + m)',explanation:'The official solution visits n cells and total degree terms summing to m.'},
  {id:'24-mc-5',exam:'2024',section:'Flows',topic:'Flows',prompt:'How can vertex-disjoint s-t paths be found using max flow?',type:'multiple-choice',options:['Split every internal vertex into in/out vertices','Run a spanning-tree algorithm','Sort all vertices by degree','Use Dijkstra on the residual graph'],answer:'Split every internal vertex into in/out vertices',explanation:'The vertex-splitting construction gives unit capacity through each internal vertex.'},
  {id:'24-mc-6',exam:'2024',section:'NP',topic:'NP completeness',prompt:'What reduction is used to prove Dominating Set NP-complete in the official solution?',type:'multiple-choice',options:['Reduce from Vertex Cover','Reduce from 2-SAT','Reduce from Shortest Path','Reduce from Minimum Spanning Tree'],answer:'Reduce from Vertex Cover',explanation:'The solution adds a wuv vertex for each edge uv and reduces from Vertex Cover.'},

  {id:'25-tf-1',exam:'2025',section:'True or false',topic:'Asymptotics',prompt:'For functions f and g, f ∈ Θ(g) if and only if f ∈ Ω(g).',type:'true-false',options:['True','False'],answer:'False',explanation:'Theta requires both upper and lower bounds.'},
  {id:'25-tf-2',exam:'2025',section:'True or false',topic:'Asymptotics',prompt:'For functions f and g, f ∈ Θ(g) if and only if f ∈ O(g) and f ∈ Ω(g).',type:'true-false',options:['True','False'],answer:'True',explanation:'This is the standard definition of Theta notation.'},
  {id:'25-tf-3',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n) = 2T(n/2) + cn, then T(n) ∈ Ω(n log n).',type:'true-false',options:['True','False'],answer:'True',explanation:'This recurrence solves to Θ(n log n), so it is also Ω(n log n).'},
  {id:'25-tf-4',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n) = 2T(n/2) + cn, then T(n) ∈ O(n).',type:'true-false',options:['True','False'],answer:'False',explanation:'The recurrence grows by Θ(n log n), not O(n).'},
  {id:'25-tf-5',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n) = 3T(n/2) + cn, then T(n) ∈ Θ(n^log₂3).',type:'true-false',options:['True','False'],answer:'True',explanation:'The leaf term n^log₂3 dominates cn.'},
  {id:'25-tf-6',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'Every undirected simple graph has a unique minimum spanning tree.',type:'true-false',options:['True','False'],answer:'False',explanation:'Equal-weight edges can produce multiple MSTs.'},
  {id:'25-tf-7',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'Any two MSTs of the same weighted graph have the same total weight.',type:'true-false',options:['True','False'],answer:'True',explanation:'All minimum spanning trees have the minimum possible total weight.'},
  {id:'25-tf-8',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'The maximum-weight edge of a weighted graph is always in no MST.',type:'true-false',options:['True','False'],answer:'False',explanation:'A maximum-weight edge can belong to an MST when it is required to connect the graph.'},
  {id:'25-tf-9',exam:'2025',section:'True or false',topic:'Complexity',prompt:'Independent Set is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A certificate can be verified by checking size and absence of internal edges.'},
  {id:'25-tf-10',exam:'2025',section:'True or false',topic:'Complexity',prompt:'Bipartite Perfect Matching reduces to Independent Set by polynomial-time reduction.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution states this reduction direction as true.'},
  {id:'25-mc-1',exam:'2025',section:'Huffman encoding',topic:'Huffman encoding',prompt:'Which pair of characters is guaranteed to receive the longest possible encoding?',type:'multiple-choice',options:['EF','AB','AC','FG'],answer:'EF',explanation:'E and F have the two smallest frequencies, 1 and 3.'},
  {id:'25-mc-2',exam:'2025',section:'Huffman encoding',topic:'Huffman encoding',prompt:'Using the official Huffman tree, what is the encoded length of “ACDC”?',type:'multiple-choice',options:['8','6','10','12'],answer:'8',explanation:'A=2, C=1, D=4, C=1, totaling 8.'},
  {id:'25-mc-3',exam:'2025',section:'Huffman encoding',topic:'Huffman encoding',prompt:'What is the encoded length of “CCCC”?',type:'multiple-choice',options:['4','8','12','16'],answer:'4',explanation:'C has depth 1 in the official tree.'},
  {id:'25-mc-4',exam:'2025',section:'Unrolling',topic:'Recurrences',prompt:'What is the Θ solution for T(n) = 3T(n/9) + √n?',type:'multiple-choice',options:['Θ(√n log n)','Θ(n)','Θ(n log n)','Θ(n log₂n)'],answer:'Θ(√n log n)',explanation:'The unrolling/Master-Theorem result is Θ(√n log n).'},
  {id:'25-mc-5',exam:'2025',section:'DAGs',topic:'Graph algorithms',prompt:'What is the running time for finding a heaviest path from s in an edge-weighted DAG?',type:'multiple-choice',options:['O(n + m)','O(n log n)','O(nm)','O(m log n)'],answer:'O(n + m)',explanation:'Topological processing plus outgoing-edge visits take O(n + m).'},
  {id:'25-mc-6',exam:'2025',section:'Flows',topic:'Flows',prompt:'Which data is used to construct a minimum cut after running max flow?',type:'multiple-choice',options:['Edges with residual capacity reachable from s','Only the source edge','Every maximum-flow edge','Edges with flow exactly zero'],answer:'Edges with residual capacity reachable from s',explanation:'BFS from s on positive residual-capacity edges gives the reachable side R.'},
  {id:'25-mc-7',exam:'2025',section:'Flows',topic:'Flows',prompt:'For the 2025 example network, what is the maximum flow value?',type:'multiple-choice',options:['3','2','5','7'],answer:'3',explanation:'The official solution gives v(f) = 3.'},
  {id:'25-mc-8',exam:'2025',section:'Minimum cuts with many edges',topic:'Flows',prompt:'How is cap′(C) related to cap(C) for c′(e) = (m+1)c(e) − 1?',type:'multiple-choice',options:['(m+1)cap(C) − |C|','(m+1)cap(C) + |C|','cap(C) − (m+1)|C|','m·cap(C)'],answer:'(m+1)cap(C) − |C|',explanation:'Summing c′ over C gives (m+1)cap(C) − |C|.'},

  {id:'16-tf-1',exam:'2016',section:'Statements',topic:'Recurrences',prompt:'The recurrence T(n) ≤ 2T(n/2) + O(n) solves to T(n) = O(n).',type:'true-false',options:['True','False'],answer:'False',explanation:'The official solution gives T(n) = n log n.'},
  {id:'16-tf-2',exam:'2016',section:'Statements',topic:'Recurrences',prompt:'The recurrence T(n) ≤ 4T(n/2) + O(n) solves to T(n) = O(n²).',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks this statement true.'},
  {id:'16-tf-3',exam:'2016',section:'Statements',topic:'Graph algorithms',prompt:'In a directed graph, BFS edge classification produces no backward edges.',type:'true-false',options:['True','False'],answer:'False',explanation:'The official correction changes the mistaken edge classification.'},
  {id:'16-tf-4',exam:'2016',section:'Statements',topic:'Graph algorithms',prompt:'In DFS edge classification on a directed graph, there are no cross edges.',type:'true-false',options:['True','False'],answer:'False',explanation:'The official solution specifies that the statement should be about an undirected graph.'},
  {id:'16-tf-5',exam:'2016',section:'Statements',topic:'Minimum spanning trees',prompt:'If the weight of an edge outside an MST T is decreased, T always remains an MST.',type:'true-false',options:['True','False'],answer:'False',explanation:'The corrected statement would refer to an edge that is an edge of T.'},
  {id:'16-tf-6',exam:'2016',section:'Statements',topic:'Complexity',prompt:'The 3-SAT problem is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks this statement true.'},
  {id:'16-tf-7',exam:'2016',section:'Statements',topic:'Sorting',prompt:'Every comparison-based sorting algorithm needs at least Ω(n log n) time.',type:'true-false',options:['True','False'],answer:'True',explanation:'The comparison-tree lower bound is Ω(n log n).'},
  {id:'16-tf-8',exam:'2016',section:'Statements',topic:'Sorting',prompt:'It is impossible to sort n integers in the range 1 through n in O(n) time.',type:'true-false',options:['True','False'],answer:'False',explanation:'The official solution says such an algorithm can exist.'},
  {id:'16-tf-9',exam:'2016',section:'Statements',topic:'Sorting',prompt:'In Huffman encoding of “NANNY”, A and Y receive equally long codewords.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks this statement true.'},
  {id:'16-mc-1',exam:'2016',section:'Longest Common Subsequence',topic:'Dynamic programming',prompt:'What recurrence base case is used for two-string LCS dp(i,j)?',type:'multiple-choice',options:['dp(i,0)=dp(0,j)=0','dp(i,j)=1','dp(i,j)=i+j','dp(i,j)=∞'],answer:'dp(i,0)=dp(0,j)=0',explanation:'The official solution initializes all border entries to zero.'},
  {id:'16-mc-2',exam:'2016',section:'Longest Common Subsequence',topic:'Dynamic programming',prompt:'What is the running time for computing LCS of strings of lengths n and m?',type:'multiple-choice',options:['O(nm)','O(n+m)','O(n log m)','O(n²m²)'],answer:'O(nm)',explanation:'There are nm cells and each cell takes constant time.'},
  {id:'16-mc-3',exam:'2016',section:'Shortest Paths',topic:'Shortest paths',prompt:'What method finds shortest paths from one source in a DAG with possible negative weights?',type:'multiple-choice',options:['Topological sort plus dynamic programming','Breadth-first search only','Greedy edge removal','Repeated Dijkstra from all sinks'],answer:'Topological sort plus dynamic programming',explanation:'The official solution uses topological order and in-degree DP.'},
  {id:'16-mc-4',exam:'2016',section:'Shortest Paths',topic:'Shortest paths',prompt:'What running time does the DAG shortest-path solution give?',type:'multiple-choice',options:['O(n + m)','O(nm)','O(n log n)','O(m log n)'],answer:'O(n + m)',explanation:'Topological sorting and DP are linear for the graph size.'},
  {id:'16-mc-5',exam:'2016',section:'NP-Completeness',topic:'NP completeness',prompt:'Which reduction proves Independent Set NP-hard in the official 2016 solution?',type:'multiple-choice',options:['Vertex Cover to Independent Set','Independent Set to Vertex Cover','3-SAT to Independent Set','Clique to Vertex Cover'],answer:'Vertex Cover to Independent Set',explanation:'The solution uses (G,k) mapped to (G,n-k).'},
  {id:'16-mc-6',exam:'2016',section:'NP-Completeness',topic:'NP completeness',prompt:'What certificate is used to verify a Dominating Set instance?',type:'multiple-choice',options:['A set D with |D|≤k and N[v]∩D≠∅','A spanning tree','A maximum matching','A topological ordering'],answer:'A set D with |D|≤k and N[v]∩D≠∅',explanation:'Every vertex must belong to D or have a neighbor in D.'},

  {id:'21-tf-1',exam:'2021',section:'True or false',topic:'Asymptotics',prompt:'If g(n)=O(f(n)) and f(n)=O(h(n)), then g(n)=O(h(n)).',type:'true-false',options:['True','False'],answer:'True',explanation:'Big-O relation is transitive.'},
  {id:'21-tf-2',exam:'2021',section:'True or false',topic:'Shortest paths',prompt:'Adding a sufficiently large constant to every edge weight makes Dijkstra correct for negative-weight edges.',type:'true-false',options:['True','False'],answer:'False',explanation:'The official solution repeats that this does not make Dijkstra correct.'},
  {id:'21-tf-3',exam:'2021',section:'True or false',topic:'Shortest paths',prompt:'Breadth-first search finds shortest paths in an undirected unweighted graph.',type:'true-false',options:['True','False'],answer:'True',explanation:'BFS gives shortest-path distances in unweighted graphs.'},
  {id:'21-tf-4',exam:'2021',section:'True or false',topic:'Flows',prompt:'In the final residual graph after a nonzero maximum flow, there is always a path from the sink to the source.',type:'true-false',options:['True','False'],answer:'False',explanation:'The official solution marks this false.'},
  {id:'21-tf-5',exam:'2021',section:'True or false',topic:'Complexity',prompt:'The decision problem “does G have an independent set of size k?” is NP-complete.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks the decision problem NP-complete.'},
  {id:'21-tf-6',exam:'2021',section:'True or false',topic:'Complexity',prompt:'The decision problem “does G have a vertex cover of size k?” is in P.',type:'true-false',options:['True','False'],answer:'False',explanation:'Vertex Cover is NP-complete.'},
  {id:'21-tf-7',exam:'2021',section:'True or false',topic:'Minimum spanning trees',prompt:'If a graph has unique edge weights, the two smallest-weight edges are always in the MST.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution marks this statement true.'},
  {id:'21-tf-8',exam:'2021',section:'True or false',topic:'Matchings',prompt:'Whether a bipartite graph has a perfect matching is in P.',type:'true-false',options:['True','False'],answer:'True',explanation:'Perfect matching in bipartite graphs is polynomial-time solvable.'},
  {id:'21-tf-9',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Deciding whether a graph has an independent set of size 5 is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'With a fixed constant k, this small decision problem is polynomial-time checkable.'},
  {id:'21-tf-10',exam:'2021',section:'True or false',topic:'Graph algorithms',prompt:'In a directed graph with n vertices and m edges, cycle detection can be done in O(n).',type:'true-false',options:['True','False'],answer:'False',explanation:'Cycle detection generally examines O(n+m) graph data.'},
  {id:'21-mc-1',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What is the tight upper bound for T(n)=2T(n/2)+O(n)?',type:'multiple-choice',options:['O(n log n)','O(n)','O(n²)','O(log n)'],answer:'O(n log n)',explanation:'This is the standard merge-sort recurrence.'},
  {id:'21-mc-2',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What is the solution for T(n)=T(n/2)+1?',type:'multiple-choice',options:['O(log n)','O(n)','O(n log n)','O(n²)'],answer:'O(log n)',explanation:'The official solution identifies the binary-search recurrence.'},
  {id:'21-mc-3',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What is the solution for T(n)=4T(n/2)+O(n)?',type:'multiple-choice',options:['O(n²)','O(n)','O(n log n)','O(n³)'],answer:'O(n²)',explanation:'The solution unrolls to n·2^log₂n = n².'},
  {id:'21-mc-4',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What is the solution for T(n)=8T(n/2)+O(n²)?',type:'multiple-choice',options:['O(n³)','O(n²)','O(n log n)','O(n)'],answer:'O(n³)',explanation:'The official solution gives O(n³).'},
  {id:'21-mc-5',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What is the solution for T(n)=T(n−1)+2?',type:'multiple-choice',options:['O(n)','O(log n)','O(n log n)','O(2ⁿ)'],answer:'O(n)',explanation:'The additive constant is repeated n times.'},
  {id:'21-mc-6',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What is the solution for T(n)=2T(n−1)?',type:'multiple-choice',options:['O(2ⁿ)','O(n)','O(n²)','O(log n)'],answer:'O(2ⁿ)',explanation:'The official solution gives exponential growth.'},

  {id:'24-long-1',exam:'2024',section:'Fast algorithms',topic:'Graph algorithms',prompt:'Which algorithmic method is the official solution for determining whether an undirected graph has a cycle?',type:'multiple-choice',options:['Compare edge and vertex counts per component','Run Dijkstra from every vertex','Use Huffman encoding','Compute all Hamiltonian cycles'],answer:'Compare edge and vertex counts per component',explanation:'A connected undirected component is cyclic when mC > nC − 1.'},
  {id:'24-long-2',exam:'2024',section:'Fast algorithms',topic:'Graph algorithms',prompt:'Which cycle-check method does the official 2024 solution give for a directed graph?',type:'multiple-choice',options:['Find strongly connected components','Use breadth-first search once','Run Prim’s algorithm','Sort vertices and edges'],answer:'Find strongly connected components',explanation:'The solution runs SCC and checks whether any SCC contains more than one vertex.'},
  {id:'24-long-3',exam:'2024',section:'Fast algorithms',topic:'Graph algorithms',prompt:'What is the official greedy placement rule for the house-antenna problem?',type:'multiple-choice',options:['Place an antenna 4 km beyond the first uncovered house, then repeat','Place one antenna at the midpoint of the whole list','Place an antenna at every house','Place antennas only at the first and last houses'],answer:'Place an antenna 4 km beyond the first uncovered house, then repeat',explanation:'The official solution places the next antenna at x0 + 4 and advances in 4-km coverage intervals.'},
  {id:'24-long-4',exam:'2024',section:'More algorithms',topic:'Dynamic programming',prompt:'Which counterexample is official for the “heaviest first” alarm algorithm?',type:'multiple-choice',options:['[2,3,2]','[1,1,1]','[9,1,9]','[4,5,6]'],answer:'[2,3,2]',explanation:'The official solution explicitly gives [2,3,2] as a counterexample.'},
  {id:'24-long-5',exam:'2024',section:'More algorithms',topic:'Dynamic programming',prompt:'Which counterexample is official for the even–odd alarm algorithm?',type:'multiple-choice',options:['[3,2,2,3]','[1,8,2,2]','[2,3,2]','[4,1,4,1]'],answer:'[3,2,2,3]',explanation:'The official solution explicitly gives [3,2,2,3] as a counterexample.'},
  {id:'24-long-6',exam:'2024',section:'More algorithms',topic:'Dynamic programming',prompt:'What recurrence is used by the correct alarm dynamic-programming solution?',type:'multiple-choice',options:['c[i]=max(L[i−1]+c[i−2], c[i−1])','c[i]=c[i−1]+c[i−2]+L[i]','c[i]=min(L[i], c[i−1])','c[i]=L[i]+sum(L)'],answer:'c[i]=max(L[i−1]+c[i−2], c[i−1])',explanation:'The official code chooses either the current item plus i−2 or the i−1 optimum.'},
  {id:'24-long-7',exam:'2024',section:'Flows',topic:'Flows',prompt:'What vertex-splitting construction is used to find vertex-disjoint s-t paths?',type:'multiple-choice',options:['Split each internal vertex into vin/vout with unit capacity','Split every edge and double all capacities','Contract s and t','Replace vertices with complete subgraphs'],answer:'Split each internal vertex into vin/vout with unit capacity',explanation:'The official solution replaces internal vertices by vin and vout and gives the internal edge unit capacity.'},
  {id:'24-long-8',exam:'2024',section:'Flows',topic:'Flows',prompt:'What is the official running-time expression for the vertex-disjoint-path reduction using max flow?',type:'multiple-choice',options:['Θ(F)','Θ(n log n)','Θ(nm log n)','Θ(n²m)'],answer:'Θ(F)',explanation:'The constructed graph has Θ(n) vertices and Θ(m) edges, so max-flow time dominates.'},
  {id:'24-long-9',exam:'2024',section:'NP',topic:'NP completeness',prompt:'What is the official certificate used to verify Dominating Set?',type:'multiple-choice',options:['D⊆V with |D|≤k and every closed neighborhood contains D','A Hamiltonian cycle','A minimum spanning tree','A topological vertex ordering'],answer:'D⊆V with |D|≤k and every closed neighborhood contains D',explanation:'The solution verifies |D|≤k and N[v]∩D≠∅ for every vertex v.'},
  {id:'24-long-10',exam:'2024',section:'NP',topic:'NP completeness',prompt:'What gadget is used in the official Dominating Set reduction from Vertex Cover?',type:'multiple-choice',options:['For each edge uv, add wuv connected to u and v','For each vertex, add a leaf','Contract every edge','Add a complete graph on all vertices'],answer:'For each edge uv, add wuv connected to u and v',explanation:'The official hint and solution use one wuv vertex for every original edge uv.'},

  {id:'25-long-1',exam:'2025',section:'DAGs',topic:'Graph algorithms',prompt:'What recurrence does the official solution give for the heaviest path from a vertex v in a DAG?',type:'multiple-choice',options:['H(v)=maxu∈N+(v)(H(u)+w(vu)), or 0 at a sink','H(v)=minu∈N+(v)H(u)','H(v)=H(v−1)+1','H(v)=sum of all vertex weights'],answer:'H(v)=maxu∈N+(v)(H(u)+w(vu)), or 0 at a sink',explanation:'The solution computes H in reverse topological order.'},
  {id:'25-long-2',exam:'2025',section:'DAGs',topic:'Graph algorithms',prompt:'What running time is used for DAG single-source shortest paths by topological ordering?',type:'multiple-choice',options:['O(n+m)','O(nm)','O(n log n)','O(m log n)'],answer:'O(n+m)',explanation:'The official solution labels the algorithm optimal because all vertices and edges must be examined.'},
  {id:'25-long-3',exam:'2025',section:'Flows',topic:'Flows',prompt:'What is the first step in the official minimum-cut pseudocode?',type:'multiple-choice',options:['Run max_flow to obtain f','Sort all edge capacities','Run Dijkstra to find a shortest path','Construct a spanning tree'],answer:'Run max_flow to obtain f',explanation:'The solution obtains f, then examines residual edges and reachable vertices.'},
  {id:'25-long-4',exam:'2025',section:'Flows',topic:'Flows',prompt:'After max flow, which residual edges are used to find the minimum-cut side?',type:'multiple-choice',options:['Edges with f(e)<c(e)','Edges with f(e)=0','All edges in the minimum-cost tree','Only outgoing source edges'],answer:'Edges with f(e)<c(e)',explanation:'The residual graph keeps edges with positive residual capacity.'},
  {id:'25-long-5',exam:'2025',section:'Flows',topic:'Flows',prompt:'What are the minimum s-t cuts for the official 2025 example?',type:'multiple-choice',options:['{s,a,c} and {s,a,b,c,d}','{s,a} and {b,c,d,t}','{dt} and {sa,ab}','Only {sa,ab}'],answer:'{s,a,c} and {s,a,b,c,d}',explanation:'The official solution gives these two vertex-side cuts.'},
  {id:'25-long-6',exam:'2025',section:'Minimum cuts with many edges',topic:'Flows',prompt:'How can a minimum cut with the most edges be found using the transformed capacities?',type:'multiple-choice',options:['Minimize |C| using the largest decrease from equal weighted cuts','Minimize only original capacity','Maximize the number of vertices in R','Ignore residual capacities'],answer:'Minimize |C| using the largest decrease from equal weighted cuts',explanation:'Transforming capacities makes cuts with equal original capacity favor larger edge counts in the objective.'},

  {id:'16-long-1',exam:'2016',section:'Longest Common Subsequence',topic:'Dynamic programming',prompt:'What is the recurrence for two-string LCS when xi=yj?',type:'multiple-choice',options:['dp(i,j)=1+dp(i−1,j−1)','dp(i,j)=dp(i−1,j)+dp(i,j−1)','dp(i,j)=dp(i,j−1)','dp(i,j)=2dp(i−1,j−1)'],answer:'dp(i,j)=1+dp(i−1,j−1)',explanation:'The official solution uses this recurrence for matching characters.'},
  {id:'16-long-2',exam:'2016',section:'Longest Common Subsequence',topic:'Dynamic programming',prompt:'What is the recurrence for three-string LCS when xi=yj=zk?',type:'multiple-choice',options:['1+dp(i−1,j−1,k−1)','max(dp(i−1,j,k),dp(i,j−1,k),dp(i,j,k−1))','dp(i,j,k−1)+1','dp(i−1,j−1,k)+dp(i,j,k−1)'],answer:'1+dp(i−1,j−1,k−1)',explanation:'The matching case extends all three prefixes by one.'},
  {id:'16-long-3',exam:'2016',section:'Shortest Paths',topic:'Shortest paths',prompt:'What is the official DAG shortest-path method for negative edge weights?',type:'multiple-choice',options:['Topologically sort, then relax in order','Run Dijkstra and assume no negative edges','Run BFS from every sink','Enumerate all simple paths'],answer:'Topologically sort, then relax in order',explanation:'The official solution first topologically sorts and then does dynamic programming.'},
  {id:'16-long-4',exam:'2016',section:'Shortest Paths',topic:'Shortest paths',prompt:'What running time is given for shortest paths in a DAG with n vertices and m edges?',type:'multiple-choice',options:['O(n+m)','O(nm)','O(n log n)','O(m log n)'],answer:'O(n+m)',explanation:'Topological sorting and the DP each scan graph information in linear aggregate time.'},
  {id:'16-long-5',exam:'2016',section:'NP-Completeness',topic:'NP completeness',prompt:'What polynomial-time reduction proves Independent Set NP-hard in the 2016 exam solution?',type:'multiple-choice',options:['(G,k) to (G,n−k)','(G,k) to (G,k+1)','(G,k) to (G,2k)','(G,k) to a DAG'],answer:'(G,k) to (G,n−k)',explanation:'The official solution states Vertex Cover ≤p Independent Set using complements.'},
  {id:'16-long-6',exam:'2016',section:'NP-Completeness',topic:'NP completeness',prompt:'What construction proves Dominating Set NP-hard in the 2016 solution?',type:'multiple-choice',options:['Add wuv connected to u and v for each edge uv','Add a leaf for every vertex','Replace edges with directed cycles','Remove all vertices of odd degree'],answer:'Add wuv connected to u and v for each edge uv',explanation:'The official reduction is Vertex Cover to Dominating Set using wuv gadgets.'},

  {id:'21-long-1',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What recurrence describes alg1 in the 2021 running-time analysis?',type:'multiple-choice',options:['T(n)=2T(n/2)+O(1)','T(n)=T(n/2)+n','T(n)=2T(n/2)+n log n','T(n)=3T(n/3)+n²'],answer:'T(n)=2T(n/2)+O(1)',explanation:'The official solution gives O(n) for alg1.'},
  {id:'21-long-2',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What recurrence describes alg2 in the 2021 running-time analysis?',type:'multiple-choice',options:['T(n)=2T(n/2)+n log n','T(n)=2T(n/2)+O(1)','T(n)=T(n/2)+n','T(n)=3T(n/3)+n²'],answer:'T(n)=2T(n/2)+n log n',explanation:'The official solution resolves this as Θ(n log²n).'},
  {id:'21-long-3',exam:'2021',section:'Running time',topic:'Recurrences',prompt:'What recurrence describes alg3 in the 2021 running-time analysis?',type:'multiple-choice',options:['T(n)=3T(n/3)+n²','T(n)=2T(n/2)+n log n','T(n)=T(n−1)+n','T(n)=8T(n/2)+n²'],answer:'T(n)=3T(n/3)+n²',explanation:'The official solution gives O(n²) for this recurrence.'},
  {id:'21-long-4',exam:'2021',section:'Local minimum',topic:'Divide and conquer',prompt:'What base-case strategy is proposed for the divide-and-conquer local-minimum algorithm?',type:'multiple-choice',options:['Brute force when n or m is at most 3','Check every possible 2×2 square','Use Dijkstra on the border','Sort the full matrix'],answer:'Brute force when n or m is at most 3',explanation:'The official solution uses brute force for matrices whose dimensions are at most 3.'},
  {id:'21-long-5',exam:'2021',section:'Graph search',topic:'Graph algorithms',prompt:'What algorithm is given as the conceptual solution to the graph bottleneck-path problem?',type:'multiple-choice',options:['Binary search on maximum steepness plus BFS','Dynamic programming in a grid','Bellman-Ford with negative edges','Greedy nearest-neighbor search'],answer:'Binary search on maximum steepness plus BFS',explanation:'The official solution can binary-search a threshold and BFS on allowed edges.'},
  {id:'21-long-6',exam:'2021',section:'Graph search',topic:'Graph algorithms',prompt:'What alternative bottleneck-edge method is proved using an MST in the 2021 solution?',type:'multiple-choice',options:['Find the MST and inspect the unique s-t path','Find the densest cut','Run all-pairs Dijkstra','Use a depth-first spanning forest'],answer:'Find the MST and inspect the unique s-t path',explanation:'The official alternative solution observes that the bottleneck edge is on the MST s-t path.'},

  {id:'24-tf-16',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n)=2T(n/2)+n², then T(n) is Ω(n log n).',type:'true-false',options:['True','False'],answer:'True',explanation:'T(n)=Θ(n²), so it is also Ω(n log n).'},
  {id:'24-tf-17',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n)=5T(n/3)+n², then T(n) is O(n^log₅3).',type:'true-false',options:['True','False'],answer:'False',explanation:'n² dominates n^log₃5, so the stated upper bound is not the correct one.'},
  {id:'24-tf-18',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n)=5T(n/3)+n², then T(n) is O(n^log₃5).',type:'true-false',options:['True','False'],answer:'False',explanation:'The n² term dominates this recurrence; n^log₃5 is not the tight O-bound.'},
  {id:'24-tf-19',exam:'2024',section:'True or false',topic:'Recurrences',prompt:'If T(n)=5T(n/3)+n², then T(n) is O(n²).',type:'true-false',options:['True','False'],answer:'True',explanation:'The n² term is at least as large as the recursive tree growth.'},
  {id:'24-tf-12b',exam:'2024',section:'True or false',topic:'Flows',prompt:'After Ford–Fulkerson computes a nonzero maximum flow, is there always a path from the sink back to the source in the final residual graph?',type:'true-false',options:['True','False'],answer:'False',explanation:'The final residual graph need not contain a sink-to-source path.'},
  {id:'24-long-11',exam:'2024',section:'NP',topic:'NP completeness',prompt:'Which reduction proves Feedback Vertex Set NP-complete in the 2024 exam solution?',type:'multiple-choice',options:['Use the same wuv gadget reduction from Dominating Set','Reduce from Maximum Flow','Reduce from Graph Coloring','Reduce from MST'],answer:'Use the same wuv gadget reduction from Dominating Set',explanation:'The solution reduces Dominating Set to Feedback Vertex Set using the wuv gadget.'},
  {id:'24-long-12',exam:'2024',section:'Flows',topic:'Flows',prompt:'Is the vertex-disjoint s-t paths decision problem in NP?',type:'multiple-choice',options:['Yes, a set of k paths can be verified in polynomial time','No, it is undecidable','Only for acyclic graphs','It is in P but not NP'],answer:'Yes, a set of k paths can be verified in polynomial time',explanation:'A solution can be checked for k paths and vertex-disjointness.'},
  {id:'24-long-13',exam:'2024',section:'Flows',topic:'Flows',prompt:'Is the vertex-disjoint s-t paths decision problem NP-complete?',type:'multiple-choice',options:['No; it is solvable by max flow','Yes, by reduction from 3-SAT','Yes, it is equivalent to Clique','No; it is uncomputable'],answer:'No; it is solvable by max flow',explanation:'The official solution says the problem is in P via vertex splitting and max flow.'},

  {id:'25-tf-11',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is Ω(n).',type:'true-false',options:['True','False'],answer:'True',explanation:'The recurrence solves to n^log₂3, which grows at least as fast as n.'},
  {id:'25-tf-12',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is Ω(n log n).',type:'true-false',options:['True','False'],answer:'True',explanation:'The solution is Θ(n^log₂3), which dominates n log n.'},
  {id:'25-tf-13',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is Ω(n²).',type:'true-false',options:['True','False'],answer:'False',explanation:'n^log₂3 is below n².'},
  {id:'25-tf-14',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is O(n).',type:'true-false',options:['True','False'],answer:'False',explanation:'The leaf term n^log₂3 dominates n.'},
  {id:'25-tf-15',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is O(n log n).',type:'true-false',options:['True','False'],answer:'False',explanation:'n^log₂3 grows faster than n log n.'},
  {id:'25-tf-16',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is O(n²).',type:'true-false',options:['True','False'],answer:'True',explanation:'n^log₂3 < n².'},
  {id:'25-tf-17',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is Θ(n^log₃2).',type:'true-false',options:['True','False'],answer:'False',explanation:'The correct exponent is log₂3.'},
  {id:'25-tf-18',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=3T(n/2)+cn, then T(n) is Θ(n^log₂3).',type:'true-false',options:['True','False'],answer:'True',explanation:'The leaf term n^log₂3 dominates the recurrence.'},
  {id:'25-tf-19',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'Every undirected simple graph has a unique minimum spanning tree.',type:'true-false',options:['True','False'],answer:'False',explanation:'Graphs with tied edge weights can have multiple MSTs.'},
  {id:'25-tf-20',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'Two minimum spanning trees of the same weighted graph have the same total weight.',type:'true-false',options:['True','False'],answer:'True',explanation:'Both attain the minimum possible spanning-tree weight.'},
  {id:'25-tf-21',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'Two minimum spanning trees of the same graph have the same number of edges.',type:'true-false',options:['True','False'],answer:'True',explanation:'Every spanning tree of an n-vertex graph has n-1 edges.'},
  {id:'25-tf-22',exam:'2025',section:'True or false',topic:'Minimum spanning trees',prompt:'A heaviest edge of a weighted graph is always excluded from every MST.',type:'true-false',options:['True','False'],answer:'False',explanation:'A heaviest edge can be necessary to connect the graph.'},
  {id:'25-tf-23',exam:'2025',section:'True or false',topic:'Complexity',prompt:'Independent Set is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A candidate set can be verified in polynomial time.'},
  {id:'25-tf-24',exam:'2025',section:'True or false',topic:'Complexity',prompt:'Independent Set ≤p Bipartite Perfect Matching.',type:'true-false',options:['True','False'],answer:'False',explanation:'The stated reduction direction is not the standard known relationship.'},
  {id:'25-tf-25',exam:'2025',section:'True or false',topic:'Complexity',prompt:'Bipartite Perfect Matching ≤p Independent Set.',type:'true-false',options:['True','False'],answer:'True',explanation:'The official solution states this reduction direction.'},
  {id:'25-tf-2T-1',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=2T(n/2)+cn, then T(n) is Ω(n).',type:'true-false',options:['True','False'],answer:'True',explanation:'The recurrence solves to Θ(n log n), which is Ω(n).'},
  {id:'25-tf-2T-2',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=2T(n/2)+cn, then T(n) is Ω(n²).',type:'true-false',options:['True','False'],answer:'False',explanation:'The recurrence is Θ(n log n), not Ω(n²).'},
  {id:'25-tf-2T-3',exam:'2025',section:'True or false',topic:'Recurrences',prompt:'If T(n)=2T(n/2)+cn, then T(n) is O(n²).',type:'true-false',options:['True','False'],answer:'True',explanation:'n log n is O(n²).'},
  {id:'25-mc-9',exam:'2025',section:'Huffman encoding',topic:'Huffman encoding',prompt:'What is the encoded length of “CAFEBABE” using the 2025 Huffman tree?',type:'multiple-choice',options:['28','22','30','32'],answer:'28',explanation:'The code lengths sum to 1+2+5+5+4+2+4+5=28.'},
  {id:'25-mc-10',exam:'2025',section:'Huffman encoding',topic:'Huffman encoding',prompt:'What is the encoded length of “FFFF” using the 2025 Huffman tree?',type:'multiple-choice',options:['20','12','16','5'],answer:'20',explanation:'F has codeword length 5, so four F characters use 20 bits.'},
  {id:'25-long-7',exam:'2025',section:'DAGs',topic:'Graph algorithms',prompt:'What time and property are used for optimal single-source shortest paths in a DAG?',type:'multiple-choice',options:['O(n+m); all vertices and edges must be examined','O(n log n); use Dijkstra','O(nm); relax every pair','O(m log n); use a priority queue'],answer:'O(n+m); all vertices and edges must be examined',explanation:'Topological sorting and edge processing take O(n+m).'},
  {id:'25-long-8',exam:'2025',section:'Flows',topic:'Flows',prompt:'What condition ensures conservation for a maximum flow value v(f)?',type:'multiple-choice',options:['Every internal vertex has equal in-flow and out-flow','Every edge carries unit flow','Only source out-flow exceeds sink in-flow','Residual capacities are zero'],answer:'Every internal vertex has equal in-flow and out-flow',explanation:'Flow conservation requires equal incoming and outgoing flow at each internal vertex.'},
  {id:'25-long-9',exam:'2025',section:'Minimum cuts with many edges',topic:'Flows',prompt:'If cap(C1)>cap(C2), what follows for the transformed capacities?',type:'multiple-choice',options:['cap′(C1)>cap′(C2)','cap′(C1)=cap′(C2)','cap′(C1)<cap′(C2)','The relation is reversed'],answer:'cap′(C1)>cap′(C2)',explanation:'The (m+1) factor preserves strict capacity differences.'},
  {id:'25-long-10',exam:'2025',section:'Minimum cuts with many edges',topic:'Flows',prompt:'For equal original cut capacities, how does transformed capacity depend on cut edge count?',type:'multiple-choice',options:['More edges gives lower transformed capacity','More edges gives higher transformed capacity','Edge count has no effect','Capacity becomes independent of m'],answer:'More edges gives lower transformed capacity',explanation:'cap′(C)=(m+1)cap(C)-|C|, so the cut with more edges has lower transformed capacity.'},

  {id:'16-tf-10',exam:'2016',section:'Statements',topic:'Sorting',prompt:'If an unsorted array A[1..n] has integers, the fastest algorithm for finding the √log n-th smallest element takes Θ(n log n) time.',type:'true-false',options:['True','False'],answer:'False',explanation:'Selection can be done faster than sorting; the official correction does not retain this bound.'},
  {id:'16-mc-7',exam:'2016',section:'Shortest Paths',topic:'Shortest paths',prompt:'For a DAG with negative edge weights, which algorithm gives shortest paths from one source?',type:'multiple-choice',options:['Topological sort followed by edge relaxation','Dijkstra without modification','Repeated breadth-first search','Greedy sink contraction'],answer:'Topological sort followed by edge relaxation',explanation:'Topological order allows each vertex to be finalized exactly once.'},
  {id:'16-mc-8',exam:'2016',section:'Shortest Paths',topic:'Shortest paths',prompt:'When Bellman-Ford is run on a graph with a negative edge but no negative cycle, what does it compute?',type:'multiple-choice',options:['Shortest distances and intermediate distance arrays','Only a maximum spanning tree','All minimum cuts','Only source-to-sink reachability'],answer:'Shortest distances and intermediate distance arrays',explanation:'The exam task asks for intermediate Bellman-Ford distance values.'},
  {id:'16-long-7',exam:'2016',section:'NP-Completeness',topic:'NP completeness',prompt:'What polynomial-time reduction proves Dominating Set NP-complete in 2016?',type:'multiple-choice',options:['Reduce Vertex Cover to Dominating Set','Reduce Dominating Set to Dijkstra','Reduce 3-SAT to MST','Reduce Vertex Cover to a DAG'],answer:'Reduce Vertex Cover to Dominating Set',explanation:'The official solution proves NP-hardness from Vertex Cover and membership in NP separately.'},
  {id:'16-long-8',exam:'2016',section:'Flow',topic:'Flows',prompt:'What valid setup is asked for in 2016 Flow task 5(a)?',type:'multiple-choice',options:['Draw 5 vertices and 5 edges with capacities and a nonzero, nonmaximum s-t flow','Draw a complete graph with 10 vertices','Give only a maximum-flow value','Prove that all capacities must be equal'],answer:'Draw 5 vertices and 5 edges with capacities and a nonzero, nonmaximum s-t flow',explanation:'The task explicitly requires a small network, capacities, and a valid nonmaximum flow.'},
  {id:'16-long-9',exam:'2016',section:'Flow',topic:'Flows',prompt:'After defining a flow, what must be drawn for 2016 Flow task 5(b)?',type:'multiple-choice',options:['The residual graph with residual capacities','Only the minimum cut','A breadth-first search tree','A spanning tree of G'],answer:'The residual graph with residual capacities',explanation:'The residual graph uses c(e)-f(e) and residual reverse edges.'},
  {id:'16-long-10',exam:'2016',section:'Flow',topic:'Flows',prompt:'In the 2016 flow example, what is the maximum flow value given in the official solution?',type:'multiple-choice',options:['3','1','5','7'],answer:'3',explanation:'The official solution identifies a flow value of 3 and a cut of capacity 3.'},
  {id:'16-long-11',exam:'2016',section:'Flow',topic:'Flows',prompt:'Which property is required for the 2016 Flow task 5(d)?',type:'multiple-choice',options:['A 4-vertex, 5-edge network with a valid nonmaximum flow and every augmenting path containing a reverse edge','A maximum flow with no residual paths','A DAG with negative capacities','A perfect matching'],answer:'A 4-vertex, 5-edge network with a valid nonmaximum flow and every augmenting path containing a reverse edge',explanation:'The task requires backward-edge use in every augmenting path.'},

  {id:'21-bigo-1',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=O(n⁴)?',type:'true-false',options:['True','False'],answer:'False',explanation:'The n⁵ term makes n⁴ an insufficient upper bound.'},
  {id:'21-bigo-2',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=O(n⁵)?',type:'true-false',options:['True','False'],answer:'True',explanation:'The leading term is 3n⁵.'},
  {id:'21-bigo-3',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=O(n⁶)?',type:'true-false',options:['True','False'],answer:'True',explanation:'n⁶ is an upper bound for a polynomial of degree 5.'},
  {id:'21-bigo-4',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=Ω(n⁴)?',type:'true-false',options:['True','False'],answer:'True',explanation:'n⁵ dominates n⁴, so f(n) is also Ω(n⁴).'},
  {id:'21-bigo-5',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=Ω(n⁵)?',type:'true-false',options:['True','False'],answer:'True',explanation:'The leading term is Θ(n⁵).'},
  {id:'21-bigo-6',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=Ω(n⁶)?',type:'true-false',options:['True','False'],answer:'False',explanation:'n⁵ is below n⁶, so f(n) is not Ω(n⁶).'},
  {id:'21-bigo-7',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=Θ(n⁴)?',type:'true-false',options:['True','False'],answer:'False',explanation:'The function grows as Θ(n⁵), not Θ(n⁴).'},
  {id:'21-bigo-8',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=Θ(n⁵)?',type:'true-false',options:['True','False'],answer:'True',explanation:'n⁵ is the leading term.'},
  {id:'21-bigo-9',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'For f(n)=3n⁵+6n⁴-n log n, is f(n)=Θ(n⁶)?',type:'true-false',options:['True','False'],answer:'False',explanation:'The function is Θ(n⁵), not Θ(n⁶).'},
  {id:'21-bigo-10',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'Let f(n)=n^1.001 and g(n)=2^1.001. Is f(n)=O(g(n))?',type:'true-false',options:['True','False'],answer:'False',explanation:'g(n) is constant, while f(n) grows polynomially.'},
  {id:'21-bigo-11',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'Let f(n)=n^1.001 and h(n)=2^1.001 n. Is f(n)=O(h(n))?',type:'true-false',options:['True','False'],answer:'False',explanation:'n^1.001 grows faster than n.'},
  {id:'21-bigo-12',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'Let g(n)=2^1.001 and h(n)=2^1.001 n. Is g(n)=O(h(n))?',type:'true-false',options:['True','False'],answer:'True',explanation:'A constant is O(n).'},
  {id:'21-bigo-13',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'If f(n)=n⁵, is f(n)=O(n⁶)?',type:'true-false',options:['True','False'],answer:'True',explanation:'n⁵ grows no faster than n⁶.'},
  {id:'21-bigo-14',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'If f(n)=n⁵, is f(n)=Ω(n⁶)?',type:'true-false',options:['True','False'],answer:'False',explanation:'n⁵ is smaller than n⁶.'},
  {id:'21-bigo-15',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'If f(n)=n⁵, is f(n)=Θ(n⁶)?',type:'true-false',options:['True','False'],answer:'False',explanation:'The degrees differ.'},
  {id:'21-bigo-16',exam:'2021',section:'Big O',topic:'Asymptotics',prompt:'Do changing logarithm bases and constant factors make O(n log₂n) and O(n log₃₂n) meaningfully different?',type:'multiple-choice',options:['No, logarithm bases differ only by a constant factor','Yes, the bases create asymptotically different growth','Only when n is small','Only for weighted graphs'],answer:'No, logarithm bases differ only by a constant factor',explanation:'The 2021 solution states the expressions are asymptotically the same.'},

  {id:'21-tf-11',exam:'2021',section:'True or false',topic:'Complexity',prompt:'If g(n)=O(f(n)) and f(n)=O(h(n)), then h(n)=O(g(n)).',type:'true-false',options:['True','False'],answer:'False',explanation:'Big-O is transitive upward, but it does not imply reverse containment.'},
  {id:'21-tf-12',exam:'2021',section:'True or false',topic:'Asymptotics',prompt:'If g(n)=O(f(n)), then f(n)=Ω(g(n)).',type:'true-false',options:['True','False'],answer:'True',explanation:'This is the standard relation between upper and lower asymptotic bounds.'},
  {id:'21-tf-13',exam:'2021',section:'True or false',topic:'Shortest paths',prompt:'In an undirected unweighted graph, Dijkstra finds shortest paths between s and t.',type:'true-false',options:['True','False'],answer:'True',explanation:'Dijkstra is valid on nonnegative-weight graphs, including unit edge weights.'},
  {id:'21-tf-14',exam:'2021',section:'True or false',topic:'Complexity',prompt:'The decision problem “does a graph have an independent set of size k?” is in P.',type:'true-false',options:['True','False'],answer:'False',explanation:'The general decision problem is NP-complete.'},
  {id:'21-tf-15',exam:'2021',section:'True or false',topic:'Complexity',prompt:'The decision problem “does a graph have an independent set of size k?” is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A candidate vertex set can be verified in polynomial time.'},
  {id:'21-tf-16',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Independent-set decision for trees is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'Maximum independent set in trees is polynomial-time solvable.'},
  {id:'21-tf-17',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Vertex-cover decision for graphs is in P.',type:'true-false',options:['True','False'],answer:'False',explanation:'General vertex-cover decision is NP-complete.'},
  {id:'21-tf-18',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Vertex-cover decision for graphs is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A candidate cover can be checked in polynomial time.'},
  {id:'21-tf-19',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Vertex-cover decision for graphs is NP-complete.',type:'true-false',options:['True','False'],answer:'True',explanation:'This is the standard NP-complete decision problem.'},
  {id:'21-tf-20',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Vertex-cover decision for trees is in P.',type:'true-false',options:['True','False'],answer:'True',explanation:'Trees have polynomial-time vertex-cover algorithms.'},
  {id:'21-tf-21',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Vertex-cover decision for trees is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'Every polynomial-time solvable problem is in NP.'},
  {id:'21-tf-22',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Vertex-cover decision for trees is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'Tree vertex cover has a polynomial-time solution.'},
  {id:'21-tf-23',exam:'2021',section:'True or false',topic:'Complexity',prompt:'If largest independent set has a polynomial-time algorithm, then P=NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'It would solve the NP-complete independent-set decision problem.'},
  {id:'21-tf-24',exam:'2021',section:'True or false',topic:'Complexity',prompt:'If largest vertex cover has a polynomial-time algorithm, then P=NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'It would solve the NP-complete vertex-cover decision problem.'},
  {id:'21-tf-25',exam:'2021',section:'True or false',topic:'Complexity',prompt:'If smallest independent set has a polynomial-time algorithm, then P=NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'The result would imply a polynomial solution for an NP-complete optimization problem.'},
  {id:'21-tf-26',exam:'2021',section:'True or false',topic:'Complexity',prompt:'If smallest vertex cover has a polynomial-time algorithm, then P=NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'It would solve vertex-cover decision efficiently.'},
  {id:'21-tf-27',exam:'2021',section:'True or false',topic:'Complexity',prompt:'3-SAT is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A satisfying assignment is a polynomial-time verifiable certificate.'},
  {id:'21-tf-28',exam:'2021',section:'True or false',topic:'Complexity',prompt:'3-SAT is NP-complete.',type:'true-false',options:['True','False'],answer:'True',explanation:'3-SAT is a canonical NP-complete problem.'},
  {id:'21-tf-29',exam:'2021',section:'True or false',topic:'Complexity',prompt:'3-SAT is in P.',type:'true-false',options:['True','False'],answer:'False',explanation:'No polynomial-time algorithm is known and 3-SAT is NP-complete.'},
  {id:'21-tf-30',exam:'2021',section:'True or false',topic:'Complexity',prompt:'The shortest-path decision problem is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A proposed path and its weight can be checked in polynomial time.'},
  {id:'21-tf-31',exam:'2021',section:'True or false',topic:'Minimum spanning trees',prompt:'If edge weights are unique, the smallest-weight edge is always in every MST.',type:'true-false',options:['True','False'],answer:'True',explanation:'The unique smallest edge is safe in every MST.'},
  {id:'21-tf-32',exam:'2021',section:'True or false',topic:'Minimum spanning trees',prompt:'If edge weights are unique, the three smallest-weight edges are always in every MST.',type:'true-false',options:['True','False'],answer:'False',explanation:'The exam only guarantees the two smallest edges, not the three.'},
  {id:'21-tf-33',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Bipartite perfect matching is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A matching certificate can be verified polynomially.'},
  {id:'21-tf-34',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Bipartite perfect matching is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'Bipartite perfect matching is polynomial-time solvable.'},
  {id:'21-tf-35',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Bipartite perfect matching is in P.',type:'true-false',options:['True','False'],answer:'True',explanation:'It can be solved with polynomial-time matching algorithms.'},
  {id:'21-tf-36',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Whether two strings have edit distance at most k is in NP.',type:'true-false',options:['True','False'],answer:'True',explanation:'A candidate edit sequence can be verified.'},
  {id:'21-tf-37',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Whether two strings have edit distance at most k is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'Edit distance is computed by polynomial-time dynamic programming.'},
  {id:'21-tf-38',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Whether two strings have edit distance at most k is in P.',type:'true-false',options:['True','False'],answer:'True',explanation:'The edit-distance table is polynomial-time computable.'},
  {id:'21-tf-39',exam:'2021',section:'True or false',topic:'Graph algorithms',prompt:'For a directed graph with n vertices and m edges, deciding whether it has a cycle takes O(n) time.',type:'true-false',options:['True','False'],answer:'False',explanation:'Cycle detection generally requires O(n+m) time.'},
  {id:'21-tf-40',exam:'2021',section:'True or false',topic:'Complexity',prompt:'An n-vertex graph independent set of size k is solvable in O(n³k²) time.',type:'true-false',options:['True','False'],answer:'False',explanation:'No general polynomial bound of this form is known for arbitrary independent-set decision.'},
  {id:'21-tf-41',exam:'2021',section:'True or false',topic:'Complexity',prompt:'An n-vertex graph vertex cover of size k is solvable in O(n⁴k²) time.',type:'true-false',options:['True','False'],answer:'False',explanation:'The general vertex-cover problem is not known to admit this polynomial bound.'},
  {id:'21-tf-42',exam:'2021',section:'True or false',topic:'Complexity',prompt:'An n-vertex graph clique of size k is solvable in O(n⁵k²) time.',type:'true-false',options:['True','False'],answer:'False',explanation:'The general clique decision problem is NP-complete.'},
  {id:'21-tf-43',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Deciding whether a graph has an independent set of size 5 is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'With fixed k=5, all choices of five vertices can be checked polynomially.'},
  {id:'21-tf-44',exam:'2021',section:'True or false',topic:'Complexity',prompt:'Deciding whether a graph has a vertex cover of size 5 is NP-complete.',type:'true-false',options:['True','False'],answer:'False',explanation:'With fixed k=5, a brute-force polynomial-time check exists.'},

  {id:'21-long-7',exam:'2021',section:'NP',topic:'NP completeness',prompt:'What is the Network Balancer decision problem?',type:'multiple-choice',options:['Given vertex weights, decide whether a cut partitions their sum equally','Find a maximum matching','Find a minimum spanning tree','Decide whether a graph is acyclic'],answer:'Given vertex weights, decide whether a cut partitions their sum equally',explanation:'The task asks whether vertices can be split into two sides with equal total weight.'},
  {id:'21-long-8',exam:'2021',section:'NP',topic:'NP completeness',prompt:'What pseudo-polynomial running time is used for Network Balancer with vertex weights?',type:'multiple-choice',options:['O(nW) by subset-sum dynamic programming','O(n log n)','O(n+m)','O(2ⁿm)'],answer:'O(nW) by subset-sum dynamic programming',explanation:'The official solution defines subset-sum DP with W as the target.'},
  {id:'21-long-9',exam:'2021',section:'NP',topic:'NP completeness',prompt:'When is the alternate meet-in-the-middle Network Balancer algorithm better?',type:'multiple-choice',options:['When n=O(log W)','When W is small','When n exceeds W','When the graph is a tree'],answer:'When n=O(log W)',explanation:'The exponential 2ⁿ bound is better when n is small relative to log W.'},
  {id:'21-long-10',exam:'2021',section:'NP',topic:'NP completeness',prompt:'Which problem is reduced to Network Balancer to prove NP-completeness?',type:'multiple-choice',options:['Subset Sum','Maximum Flow','Shortest Path','Minimum Spanning Tree'],answer:'Subset Sum',explanation:'The official reduction is from Subset Sum.'},
]

